static int VNAShell_readLine(char *line, int max_size)
{
  // Read line from input stream
  uint8_t c;
  char *ptr = line;
  while (1) {
    // Return 0 only if stream not active
    if (streamRead(shell_stream, &c, 1) == 0)
      return 0;
