2270	static void VNAShell_executeLine(char *line)
2271	{
2272	  // Parse and execute line
2273	  char *lp = line, *ep;
2274	  shell_nargs = 0;
2275	  while (*lp != 0) {
2276	    // Skipping white space and tabs at string begin.
2277	    while (*lp == ' ' || *lp == '\t') lp++;
2278	    // If an argument starts with a double quote then its delimiter is another quote, else
2279	    // delimiter is white space.
2280	    ep = (*lp == '"') ? strpbrk(++lp, "\"") : strpbrk(lp, " \t");
2281	    // Store in args string
2282	    shell_args[shell_nargs++] = lp;
2283	    // Stop, end of input string
2284	    if ((lp = ep) == NULL) break;
2285	    // Argument limits check
2286	    if (shell_nargs > VNA_SHELL_MAX_ARGUMENTS) {
2287	      shell_printf("too many arguments, max " define_to_STR(
2288	          VNA_SHELL_MAX_ARGUMENTS) "" VNA_SHELL_NEWLINE_STR);
2289	      return;
2290	    }
2291	    // Set zero at the end of string and continue check
2292	    *lp++ = 0;
2293	  }
2294	  if (shell_nargs == 0) return;
2295	  // Execute line
2296	  const VNAShellCommand *scp;
2297	  for (scp = commands; scp->sc_name != NULL; scp++) {
2298	    if (strcmp(scp->sc_name, shell_args[0]) == 0) {
