2305	      } else {
2306	        scp->sc_function(shell_nargs - 1, &shell_args[1]);
2307	      }
2308	      return;
2309	    }
2310	  }
2311	  shell_printf("%s?" VNA_SHELL_NEWLINE_STR, shell_args[0]);
